export const legalDocuments={
terms:{title:'Terms of Use',sections:[['About StrataX','StrataX is a subsurface interpretation workspace operated by Terracode Analytics Limited. Contact contact@terracodeanalytics.com for support or policy enquiries. These terms cover the features actually available in the application; a listed or illustrated capability is not a promise that it is implemented.'],['Accounts and authority','You must be legally able to accept these terms, protect your credentials, and have authority to use any well, client, geological, location or supporting information you enter. StrataX uses the shared TerraCode Firebase identity system; changing your password can affect other TerraCode applications using that account.'],['Permitted use','You may use StrataX for lawful technical, educational and business work subject to the Acceptable Use Policy and any signed agreement. Do not bypass access controls or interfere with the service.'],['Data and professional review','You retain ownership of submitted material. You permit the storage, transmission and processing necessary to provide the features you request. Scientific interpretations and derived outputs require review by competent professionals and source validation before operational, commercial, safety or investment decisions. Synthetic examples are not field results.'],['Availability and governing terms','Features may change or be unavailable. Access may be suspended for misuse, security or legal requirements. Signed agreements take priority where they conflict with these terms. No subscription or payment is introduced by this account setup. Material changes may require renewed acceptance.']]},
privacy:{title:'Privacy Policy',sections:[['Information we handle','StrataX handles account identity, email address, StrataX profile details, policy acknowledgements, browser preferences, local workspace information and limited service/security records. The current account release does not upload scientific source files or project datasets to a StrataX backend.'],['Why we use information','We use information to authenticate users, maintain accounts, send requested account emails, record policy acceptance, prevent abuse, support users and maintain reliability. We do not sell personal information or use advertising trackers in this release.'],['Storage and service providers','Firebase Authentication provides shared TerraCode identity. StrataX account profiles and policy acceptance are stored in Google Cloud Firestore in us-central1. Workspace drafts remain in browser storage scoped to the signed-in Firebase UID; browser storage is not server-enforced isolation or encryption and should be used only on trusted devices. Existing unscoped drafts are preserved separately as recovery data and are not automatically assigned to an account. Clearing browser data can remove local drafts. Cross-device project backup is not provided in this release.'],['Emails and international processing','Requested account messages are delivered through TerraCode’s SMTP provider, SpaceMail. Google Cloud, Firebase and the email provider process the information necessary for their services, potentially outside your country. We use authenticated access, scoped application records, secure transport and provider encryption at rest. Account links and passwords are excluded from application logs.'],['Retention and your choices','Account and acceptance records remain while needed to provide the service, maintain an acceptance history or meet security and legal obligations. There is no promise of automatic project backup or a fixed recovery window. You can request access, correction or deletion by contacting contact@terracodeanalytics.com; identity verification and lawful retention exceptions may apply. Deleting a shared TerraCode identity can affect other apps, so account requests must distinguish StrataX records from the shared identity.']]},
'acceptable-use':{title:'Acceptable Use Policy',sections:[['Use responsibly','Only upload or enter information you are entitled to use. Respect client confidentiality, intellectual property, applicable laws and professional obligations.'],['Prohibited activity','Do not attempt unauthorized access, credential attacks, automated account-email abuse, malware distribution, service disruption or evasion of security and usage limits. Do not misrepresent synthetic examples or unfinished functions as validated scientific results.'],['Enforcement','TerraCode may restrict access to investigate security threats, misuse, breaches or legal requirements. Report concerns to contact@terracodeanalytics.com.']]},
'ai-processing':{title:'AI and Third-Party Processing Disclosure',sections:[['Current account release','This release connects Firebase authentication, Google Cloud account/policy storage and the SMTP provider for account messages. No AI service, OCR service or semantic-search backend is connected by this authentication release.'],['Future processing features','When a feature introduces AI or another external processor, StrataX will identify its role and necessary data handling before that feature is used. Accepting this document is not authorization to send all local project data to an AI provider.'],['Professional judgement','AI-generated content, if introduced later, must be identified and reviewed. It is not a substitute for original evidence, validated scientific methods or qualified professional judgement.']]},
'data-ownership':{title:'Data Ownership and Confidentiality',sections:[['Ownership','You retain ownership of your well, project, geological, client and supporting material. You must have permission to use it. TerraCode receives only the rights necessary to provide the features you request.'],['Current storage boundary','Scientific files are not uploaded by this release. Workspace drafts remain on the device/browser where they are created, scoped by account identifier. Profile and policy records are stored in the StrataX account backend. Signing out hides the active workspace but does not erase saved drafts from the device.'],['Confidentiality and deletion','Use trusted devices for confidential work. Browser storage can be inspected by someone with access to the browser profile. Do not rely on the current release for guaranteed backup, recovery or regulatory archiving. Contact contact@terracodeanalytics.com for StrataX account-record access or deletion requests.']]},
disclaimer:{title:'Disclaimer and Limitation of Liability',sections:[['Scientific limitations','Subsurface interpretations are uncertain and can be non-unique. Verify input quality, units, depth references, assumptions, applicability and provenance. Synthetic curves, maps and summaries are illustrative and must not be used as measurements or calculated field results.'],['Professional review','StrataX does not replace qualified geological, petrophysical, geophysical or engineering judgement, independent validation or field verification. Do not base drilling, safety, construction, environmental, investment or operational decisions solely on application output.'],['Service and liability','To the extent permitted by applicable law, the service is provided without a guarantee of uninterrupted availability, error-free output or fitness for a particular purpose. Liability limitations remain subject to applicable law and any signed agreement; nothing excludes liability that cannot lawfully be excluded.']]},
cookies:{title:'Cookie and Browser Storage Policy',sections:[['Essential storage','StrataX uses Firebase authentication persistence and browser storage for session continuity, the remembered-session choice, email-link completion, account-scoped workspace drafts and interface settings. Essential Google/Firebase security storage may also be used during sign-in.'],['Your choices','The remembered-session option stores a session for up to 30 days; when unchecked, session persistence lasts for the browser session. Signing out ends StrataX’s active session. Clearing or blocking browser storage may sign you out, disrupt account-link completion or remove local drafts.'],['No advertising trackers','This release does not add advertising cookies or non-essential analytics. If those are introduced, this policy and any required consent controls will be updated. Privacy enquiries: contact@terracodeanalytics.com.']]}
};
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function legalPage(route){const doc=legalDocuments[route];return `<main class="legal-page"><a class="legal-back" href="#home">← Back to StrataX</a><div class="eyebrow">STRATAX · LEGAL POLICIES</div><h1>${escape(doc.title)}</h1><p>Version 1.0 · Effective 26 October 2026</p>${doc.sections.map(([title,text])=>`<section><h2>${escape(title)}</h2><p>${escape(text)}</p></section>`).join('')}<p>Contact: <a href="mailto:contact@terracodeanalytics.com">contact@terracodeanalytics.com</a></p></main>`;}
